-- Supabase/PostgreSQL mirror of the two required SQLite schemas.
-- Run this once in Supabase SQL Editor. Runtime cloud data is stored here.
CREATE TABLE IF NOT EXISTS student(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,roll_no TEXT NOT NULL UNIQUE,name TEXT NOT NULL,dept TEXT NOT NULL,trained BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS equipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,requires_training BOOLEAN NOT NULL DEFAULT FALSE,units_total INTEGER NOT NULL CHECK(units_total>=0),units_available INTEGER NOT NULL CHECK(units_available>=0),version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS policy(name TEXT PRIMARY KEY,value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS booking(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES student(id),equipment_id BIGINT NOT NULL REFERENCES equipment(id),slot TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(student_id,equipment_id,slot));
CREATE TABLE IF NOT EXISTS notification(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,roll_no TEXT NOT NULL,message TEXT NOT NULL,dedupe_key TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency(key TEXT PRIMARY KEY,tool_name TEXT NOT NULL,result JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS thread(id TEXT PRIMARY KEY,student_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS message(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES thread(id),seq INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('user','model')),text TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(thread_id,seq));
CREATE TABLE IF NOT EXISTS run(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES thread(id),status TEXT NOT NULL CHECK(status IN('queued','running','succeeded','failed','cancelled','dead')),model TEXT NOT NULL,tokens_in INTEGER NOT NULL DEFAULT 0,tokens_out INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,available_at DOUBLE PRECISION NOT NULL,lease_owner TEXT,lease_until DOUBLE PRECISION,cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS run_claimable ON run(status,available_at);
CREATE TABLE IF NOT EXISTS run_step(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id TEXT NOT NULL REFERENCES run(id),seq INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('model','tool')),tokens_in INTEGER NOT NULL DEFAULT 0,tokens_out INTEGER NOT NULL DEFAULT 0,text TEXT,tool_calls JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(run_id,seq));
CREATE TABLE IF NOT EXISTS tool_call(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_step_id BIGINT NOT NULL UNIQUE REFERENCES run_step(id),tool_name TEXT NOT NULL,args JSONB NOT NULL,result JSONB NOT NULL,ok BOOLEAN NOT NULL,latency_ms INTEGER NOT NULL,idempotency_key TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO student(id,roll_no,name,dept,trained) VALUES(1,'22CS045','Priya Raman','CSE',true),(2,'22IT017','Arjun Kumar','IT',false),(3,'22EC031','Divya Sekar','ECE',true) ON CONFLICT(id) DO UPDATE SET roll_no=excluded.roll_no,name=excluded.name,dept=excluded.dept,trained=excluded.trained;
INSERT INTO equipment(id,name,category,requires_training,units_total,units_available,version) VALUES(1,'Arduino Uno Kit','embedded systems',false,3,3,0),(2,'Digital Oscilloscope','electronics',true,1,1,0),(3,'FPGA Development Board','digital design',true,2,1,0),(4,'Raspberry Pi 5 Kit','iot',false,2,2,0) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,requires_training=excluded.requires_training,units_total=excluded.units_total;
INSERT INTO policy(name,value) VALUES('max_active_bookings',2) ON CONFLICT(name) DO UPDATE SET value=excluded.value;
